#!/usr/bin/env bash
# Generated by: GPT-6 (Codex)
# 离线集成测试：使用已有插件作缓存，在临时 home 中安装和回滚。
set -euo pipefail
source "$(dirname -- "${BASH_SOURCE[0]}")/lib.sh"
fixture=$(mktemp -d "${TMPDIR:-/tmp}/dotfiles-test.XXXXXXXX")
cleanup() {
  local result=$?
  tmux -S "$fixture/tmux.socket" kill-server 2>/dev/null || true
  if (( result == 0 )); then
    rm -rf -- "$fixture"
  else
    echo "Test artifacts: $fixture" >&2
  fi
}
trap cleanup EXIT
test_home="$fixture/home"
test_repo="$fixture/repo with spaces"
mkdir -p "$test_home" "$test_repo"
# 复制缓存避免重复联网；排除外层 .git，保留插件自己的 Git 元数据。
tar -C "$DOTFILES_ROOT" --exclude='./.git' -cf - . | tar -C "$test_repo" -xf -
while IFS=$'\t' read -r kind name url revision; do
  if [[ $kind != zsh ]]; then
    continue
  fi
  [[ -d $DF_HOME/.zsh/$name/.git ]] || die "Install $name before running tests."
  git config --file "$fixture/gitconfig" "url.file://$DF_HOME/.zsh/$name.insteadOf" "$url"
done < "$DOTFILES_ROOT/deps/git-components.tsv"
run() {
  env HOME="$test_home" DOTFILES_TARGET_HOME="$test_home" \
    XDG_CACHE_HOME="$test_home/.cache" GIT_CONFIG_GLOBAL="$fixture/gitconfig" "$@"
}

before=$(find "$test_home" -mindepth 1 -print)
run "$test_repo/install.sh" --check
[[ $(find "$test_home" -mindepth 1 -print) == "$before" ]] || die '--check wrote to the target home.'

# 分别覆盖普通文件、目录和失效链接，验证三种冲突都可恢复。
printf '# original zsh\n' > "$test_home/.zshrc"
mkdir "$test_home/.vim"
printf 'keep vim data\n' > "$test_home/.vim/user-note"
ln -s missing-original "$test_home/.zshenv"
run "$test_repo/install.sh" --apply
backups=("$test_home"/.local/state/dotfiles/backups/*)
first=${backups[0]##*/}
run "$test_repo/install.sh" --apply
backups=("$test_home"/.local/state/dotfiles/backups/*)
[[ ${#backups[@]} == 2 ]] || die 'Expected two separate backups.'
for backup in "${backups[@]}"; do
  [[ ${backup##*/} == "$first" ]] || [[ ! -s $backup/links.tsv ]] || die 'Second install was not idempotent.'
done

# 用户替换了一个链接后，回滚必须整次停止，不能只恢复了一半。
unlink "$test_home/.zshrc"
printf 'my later edit\n' > "$test_home/.zshrc"
if run "$test_repo/scripts/rollback.sh" "$first"; then
  die 'Rollback discarded a later edit.'
fi
[[ -L $test_home/.vim ]] || die 'Rollback partially changed other entries.'
mv "$test_home/.zshrc" "$test_home/later-edit.saved"
ln -s "$test_repo/config/zsh/.zshrc" "$test_home/.zshrc"
run "$test_repo/scripts/rollback.sh" "$first"
[[ $(cat "$test_home/.zshrc") == '# original zsh' ]] || die 'Original file not restored.'
[[ $(readlink "$test_home/.zshenv") == missing-original ]] || die 'Dangling link not restored.'
[[ $(cat "$test_home/.vim/user-note") == 'keep vim data' ]] || die 'Original directory not restored.'
[[ ! -e $test_home/.tmux.conf && ! -L $test_home/.tmux.conf ]] || die 'New link not removed.'
[[ -d $test_home/.zsh/zsh-autosuggestions/.git ]] || die 'Rollback deleted downloaded plugins.'
run "$test_repo/install.sh" --apply

# 实际执行目录跳转、文件名和内容搜索，包括中文与空格路径。
mkdir -p "$fixture/search/space dir" "$fixture/search/.git" "$fixture/search/ignored"
printf 'build output\n' > "$fixture/search/ignored/output"
printf 'ignored/\n' > "$fixture/search/.gitignore"
printf 'dotfiles_needle\n' > "$fixture/search/space dir/中文 file.txt"
printf 'hidden\n' > "$fixture/search/.hidden"
cat > "$fixture/jump.zsh" <<'ZSH'
# Generated by: GPT-6 (Codex)
cd "$TEST_SEARCH"
j "space dir"
[[ $PWD == "$TEST_SEARCH/space dir" ]] || exit 1
ZSH
run env TEST_SEARCH="$fixture/search" _ZO_DATA_DIR="$fixture/zoxide" \
  DOTFILES_JUMP_TEST="$fixture/jump.zsh" TERM=xterm-256color \
  script -qec 'zsh -d -i "$DOTFILES_JUMP_TEST"' /dev/null </dev/null
(
  cd "$fixture/search"
  finder=$(command -v fdfind || command -v fd)
  "$finder" --type f --hidden --exclude .git | "$test_repo/config/vim/.vim/bundle/fzf/bin/fzf" --filter='中文 file.txt' | rg -F 'space dir/中文 file.txt'
  if "$finder" --type f --hidden --exclude .git | rg -q '^ignored/'; then
    die 'fd ignored-file filtering failed.'
  fi
  rg --vimgrep dotfiles_needle | rg -F 'space dir/中文 file.txt:1:1:dotfiles_needle'
)

# 用两个独立 Vim 进程验证持久撤销，只编辑临时文件。
printf 'before\n' > "$fixture/undo.txt"
run vim -i NONE -n -es -u "$test_home/.vimrc" "$fixture/undo.txt" '+call setline(1, "after")' '+wq'
run vim -i NONE -n -es -u "$test_home/.vimrc" "$fixture/undo.txt" '+undo' '+wq'
[[ $(cat "$fixture/undo.txt") == before ]] || die 'Persistent undo failed.'

# 独立 socket 避免改变现有 tmux 会话；退出时只清理该测试服务器。
run tmux -S "$fixture/tmux.socket" -f "$test_home/.tmux.conf" new-session -d -s dotfiles-test 'sleep 30'
[[ $(tmux -S "$fixture/tmux.socket" show-options -gv base-index) == 1 ]]
[[ $(tmux -S "$fixture/tmux.socket" show-options -gv mouse) == on ]]
[[ $(tmux -S "$fixture/tmux.socket" show-options -gwv mode-keys) == vi ]]
echo 'PASS: offline clone, install twice, rollback protection/restoration, zoxide, search, persistent undo, isolated tmux'
